fn settings_adapter()->Result<settings::Adapter>{settings::Adapter::parse(&serde_json::to_vec(&json!({"kind":"modern_synthetic_AD368_room_settings_v1","producer_sha256":PRODUCER_SHA,"edit_sha256":settings::EDIT_SHA,"layout_sha256":settings::LAYOUT_SHA,"native_sha256":settings::NATIVE_SHA}))?)}
fn accept_bounded(listener:&TcpListener)->Result<TcpStream>{listener.set_nonblocking(true)?;let end=Instant::now()+Duration::from_secs(15);loop{match listener.accept(){Ok((s,_))=>{s.set_nonblocking(false)?;return Ok(s)},Err(e)if e.kind()==std::io::ErrorKind::WouldBlock=>{ensure!(Instant::now()<end,"owned producer accept deadline");thread::sleep(Duration::from_millis(2));},Err(e)=>return Err(e.into())}}}
fn summary_body(id:u32,name:&[u8],mode:u8,map:u16,owner:&[u8],fields:[u8;5])->Vec<u8>{let mut b=vec![213,0];b.extend(id.to_le_bytes());b.extend(name);b.push(0);b.push(mode);b.extend(map.to_le_bytes());b.push(fields[0]);b.extend(owner);b.push(0);b.extend(&fields[1..]);b}
fn configuration_body(id:u32,name:&[u8],pwd:&[u8],attr:u8,capacity:u8,options:[u8;4],selections:&[u8])->Vec<u8>{let mut b=vec![213,1];b.extend(id.to_le_bytes());b.extend(name);b.push(0);b.extend(pwd);b.push(0);b.extend([attr,capacity]);b.extend(options);b.push(selections.len() as u8);b.extend(selections);b}
fn settings_at(r:&mut Runtime,n:u64)->settings::Snapshot{until(r,|r|r.java_room_settings_snapshot().is_some_and(|s|s.revision==n));let s=r.java_room_settings_snapshot().unwrap();assert_eq!(s.stream_arrivals,n);s}
