fn decoder_checks(data:&Value)->Result<Value>{
 let saved0=hex(data["summary"].as_str().unwrap());let saved1=hex(data["configuration"].as_str().unwrap());let mut valid=0;let mut invalid=0;
 for body in [&saved0,&saved1]{settings::decode(body)?;valid+=1;for n in 0..body.len(){assert!(settings::decode(&body[..n]).is_err());invalid+=1;}let mut extra=body.clone();extra.push(0);assert!(settings::decode(&extra).is_err());invalid+=1;}
 for tag in 2..=255 {let mut b=saved0.clone();b[1]=tag;assert!(settings::decode(&b).is_err());invalid+=1;}
 for map in [0,0x101,0x234,0xff9c,0xffff]{let b=summary_body(u32::MAX,b"N",255,map,b"O",[255,1,2,3,4]);match settings::decode(&b)?{settings::Packet::Summary(s)=>{assert_eq!(s.map_word,map);assert_eq!(s.option0,255);assert_eq!(s.summary,[255,1,2,3,4]);assert_eq!(s.raw_body,b)},_=>unreachable!()};valid+=1;}
 let max=summary_body(u32::MAX,&vec![b'N';89],0,564,&vec![b'O';27],[0;5]);assert_eq!(max.len(),132);settings::decode(&max)?;valid+=1;
 let max=configuration_body(u32::MAX,&vec![b'N';89],b"1234",255,200,[7,2,127,31],&[1,2,3,4,5,6,7,255]);assert_eq!(max.len(),116);settings::decode(&max)?;valid+=1;
 for k in 0..=8 {let b=configuration_body(1,b"N",b"",255,200,[7,2,127,31],&vec![255;k]);settings::decode(&b)?;valid+=1;}
 let invalid_bodies=vec![summary_body(0,b"N",0,0,b"O",[0;5]),summary_body(1,b"",0,0,b"O",[0;5]),summary_body(1,&vec![b'N';90],0,0,b"O",[0;5]),summary_body(1,b"N",0,0,b"",[0;5]),summary_body(1,b"N",0,0,&vec![b'O';28],[0;5]),summary_body(1,&[0x81],0,0,b"O",[0;5]),summary_body(1,b"N",0,0,b"O\x1f",[0;5]),configuration_body(1,b"N",b"12345",0,2,[0;4],&[]),configuration_body(1,b"N",&[0x81],0,2,[0;4],&[]),configuration_body(1,b"N",b"",0,1,[0;4],&[]),configuration_body(1,b"N",b"",0,201,[0;4],&[]),configuration_body(1,b"N",b"",0,2,[0;4],&[1]),configuration_body(1,b"N",b"",0,2,[8,2,1,1],&[]),configuration_body(1,b"N",b"",0,2,[7,3,1,1],&[]),configuration_body(1,b"N",b"",0,2,[7,2,0,1],&[]),configuration_body(1,b"N",b"",0,2,[7,2,128,1],&[]),configuration_body(1,b"N",b"",0,2,[7,2,1,32],&[]),configuration_body(1,b"N",b"",0,2,[7,2,1,1],&[0])];
 for b in invalid_bodies {assert!(settings::decode(&b).is_err(),"accepted malformed {:02x?}",b);invalid+=1;}
 for k in [9,127,128,255]{let mut b=configuration_body(1,b"N",b"",0,2,[0;4],&[]);*b.last_mut().unwrap()=k;assert!(settings::decode(&b).is_err());invalid+=1;}
 Ok(json!({"case":"new D5 decoder exact schema/length/CString CP950/name89/owner27/pwd4/fullDWORD/fullmapWORD/rawBYTE/capacityBYTE200/options/selection0..8 and nonzero; malformed signedK and all other subtypes refused. Nonzero summary/raw attributes structural probes only, not Java capture","pass":true,"valid_probes":valid,"invalid_probes":invalid}))
}
